// Reviews are free text the user wrote. Putting them back into a value="" or a
// <textarea> unescaped would break the field on the first quote or angle bracket.
function escapeHtml(value) {
    return String(value ?? '')
        .replace(/&/g, '&amp;')
        .replace(/</g, '&lt;')
        .replace(/>/g, '&gt;')
        .replace(/"/g, '&quot;');
}

